using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
namespace Shared;
public class Airline { public Guid Id { get; set; } = Guid.NewGuid(); [MaxLength(120)] public string Name { get; set; } = ""; [MaxLength(3)] public string IataCode { get; set; } = ""; public string Country { get; set; } = ""; public bool IsActive { get; set; } = true; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public List<Review> Reviews { get; set; } = []; public List<FlightPrice> Prices { get; set; } = []; public List<Flight> Flights { get; set; } = []; public List<EnvironmentalMeasurement> EnvironmentalMeasurements { get; set; } = []; public AirlineStatistic? Statistics { get; set; } }
public class User { public Guid Id { get; set; } = Guid.NewGuid(); [MaxLength(254)] public string Email { get; set; } = ""; public string PasswordHash { get; set; } = ""; public string DisplayName { get; set; } = ""; public string Role { get; set; } = "USER"; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public DateTime UpdatedAt { get; set; } = DateTime.UtcNow; public List<SavedAirline> SavedAirlines { get; set; } = []; }
public class Review { public Guid Id { get; set; } public Guid EventId { get; set; } public Guid AirlineId { get; set; } public Airline? Airline { get; set; } public int Rating { get; set; } public string ReviewText { get; set; } = ""; public DateTime CreatedAt { get; set; } public SentimentResult? SentimentResult { get; set; } }
public class SentimentResult { public Guid Id { get; set; } = Guid.NewGuid(); public Guid EventId { get; set; } public Guid ReviewId { get; set; } public Review? Review { get; set; } public Guid AirlineId { get; set; } public string Sentiment { get; set; } = "Neutral"; public string Topics { get; set; } = ""; public DateTime CreatedAt { get; set; } }
public class FlightPrice { public Guid Id { get; set; } = Guid.NewGuid(); public Guid EventId { get; set; } public Guid AirlineId { get; set; } public Airline? Airline { get; set; } public string Origin { get; set; } = ""; public string Destination { get; set; } = ""; [Column(TypeName="numeric(10,2)")] public decimal Price { get; set; } public string Currency { get; set; } = "USD"; public DateTime TravelDate { get; set; } public DateTime CollectedAt { get; set; } }
public class Flight { public Guid Id { get; set; } = Guid.NewGuid(); public Guid EventId { get; set; } public Guid AirlineId { get; set; } public Airline? Airline { get; set; } public string FlightNumber { get; set; } = ""; public string Origin { get; set; } = ""; public string Destination { get; set; } = ""; public DateTime DepartureTime { get; set; } public DateTime ArrivalTime { get; set; } public string Status { get; set; } = "Scheduled"; public int? Terminal { get; set; } public bool IsArrival { get; set; } public string Source { get; set; } = "Demo"; public DateTime CollectedAt { get; set; } }
public class Destination { public Guid Id { get; set; } = Guid.NewGuid(); public string Code { get; set; } = ""; public string City { get; set; } = ""; public string Country { get; set; } = ""; }
public class EnvironmentalMeasurement { public Guid Id { get; set; } = Guid.NewGuid(); public Guid EventId { get; set; } public Guid AirlineId { get; set; } public Airline? Airline { get; set; } public decimal Co2KgPerPassengerKm { get; set; } public decimal FuelEfficiencyScore { get; set; } public DateTime MeasuredAt { get; set; } }
public class AirlineStatistic { [Key] public Guid AirlineId { get; set; } public Airline? Airline { get; set; } public decimal AverageRating { get; set; } public decimal PositiveSentimentPercent { get; set; } public decimal StaffScore { get; set; } public decimal ServiceScore { get; set; } public string PositiveTopics { get; set; } = ""; public string Complaints { get; set; } = ""; public decimal AveragePrice { get; set; } public decimal LowestPrice { get; set; } public decimal HighestPrice { get; set; } public int FlightsPerWeek { get; set; } public int DestinationCount { get; set; } public int RouteCount { get; set; } public decimal EnvironmentalScore { get; set; } public decimal AverageCo2 { get; set; } public decimal PassengerExperienceScore { get; set; } public decimal PriceScore { get; set; } public decimal AvailabilityScore { get; set; } public decimal OverallScore { get; set; } public DateTime UpdatedAt { get; set; } = DateTime.UtcNow; }
public class AirlineStatisticHistory { [Key] public Guid Id { get; set; } = Guid.NewGuid(); public Guid AirlineId { get; set; } public decimal AverageRating { get; set; } public decimal PositiveSentimentPercent { get; set; } public decimal StaffScore { get; set; } public decimal ServiceScore { get; set; } public string PositiveTopics { get; set; } = ""; public string Complaints { get; set; } = ""; public decimal AveragePrice { get; set; } public decimal LowestPrice { get; set; } public decimal HighestPrice { get; set; } public int FlightsPerWeek { get; set; } public int DestinationCount { get; set; } public int RouteCount { get; set; } public decimal EnvironmentalScore { get; set; } public decimal AverageCo2 { get; set; } public decimal PassengerExperienceScore { get; set; } public decimal PriceScore { get; set; } public decimal AvailabilityScore { get; set; } public decimal OverallScore { get; set; } public DateTime UpdatedAt { get; set; } = DateTime.UtcNow; public DateTime SnapshotAt { get; set; } = DateTime.UtcNow; }
public class AdminNote { public Guid Id { get; set; } = Guid.NewGuid(); public Guid AirlineId { get; set; } public Airline? Airline { get; set; } public Guid UserId { get; set; } public User? User { get; set; } public string Content { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public DateTime UpdatedAt { get; set; } = DateTime.UtcNow; }
public class SavedAirline { public Guid UserId { get; set; } public User? User { get; set; } public Guid AirlineId { get; set; } public Airline? Airline { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class RawData { public Guid Id { get; set; } = Guid.NewGuid(); public Guid EventId { get; set; } public string Topic { get; set; } = ""; public string Payload { get; set; } = ""; public bool Processed { get; set; } public string? Error { get; set; } public DateTime ReceivedAt { get; set; } = DateTime.UtcNow; }
public record ReviewEvent(Guid EventId, Guid AirlineId, int Rating, string ReviewText, DateTime CreatedAt);
public record SentimentEvent(Guid EventId, Guid SourceEventId, Guid AirlineId, int Rating, string Sentiment, string[] Topics, DateTime CreatedAt);
public record PriceEvent(Guid EventId, Guid AirlineId, string Origin, string Destination, decimal Price, string Currency, DateTime TravelDate, DateTime CollectedAt);
public record FlightEvent(Guid EventId, Guid AirlineId, string FlightNumber, string Origin, string Destination, DateTime DepartureTime, DateTime ArrivalTime, string Status, int? Terminal, bool IsArrival, string Source, DateTime CollectedAt);
public record EnvironmentEvent(Guid EventId, Guid AirlineId, decimal Co2KgPerPassengerKm, decimal FuelEfficiencyScore, DateTime MeasuredAt);
